mapper.select:
SELECT ,
FROM product p LEFT JOIN `user` u ON p.user_id = u.id LEFT JOIN category c ON p.category_id = c.id
p.deleted = 0
AND (p.title LIKE CONCAT('%', #{query.keyword}, '%') OR p.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND p.category_id = #{query.categoryId}
AND p.status = #{query.status}
AND p.user_id = #{query.sellerId}
AND p.price >= #{query.minPrice}
AND p.price <= #{query.maxPrice}
ORDER BY p.price ASC, p.id DESC ORDER BY p.price DESC, p.id DESC ORDER BY p.view_count DESC, p.id DESC ORDER BY p.create_time DESC, p.id DESC
